import React, { Component } from "react";
import settingsGetter from "./libs/settingsGetter";
import FormInput from "./libs/FormInput";
import FormMain from "./libs/FormMain";
import EventEmitter from "./libs/EventEmitter";
import utils from "./libs/utils";
import historySearch from "./libs/historySearch";

import "./App.css";

class App extends Component {
  constructor() {
    super();
    this.state = { 
      data: [], 
      hide: true, 
      loading: true // State to control loader visibility
    };

    EventEmitter.on("toggleSidebar", () => this.toggle());
    EventEmitter.on("hideSidebar", () => this.hide());
    EventEmitter.on("showSidebar", () => this.show());
    EventEmitter.on("dataReceived", () => this.hide());

    document.addEventListener("hideSidebar", () => this.hide());
    document.addEventListener("showSidebar", () => this.show());

    window.onpopstate = () => {
      if (this.state.inputs) {
        FormMain.reset();
        FormMain.setDefaults(this.state.inputs);
        historySearch.setSearchFromHistory(this.state.inputs);
      }
    };
  }

  toggle() {
    if (this.state.hide) {
      EventEmitter.emit("showSidebar");
    } else {
      EventEmitter.emit("hideSidebar");
    }
  }

  hide() {
    this.setState({ hide: true });
    document.body.classList.add("sidebar-hidden");
    document.body.classList.remove("sidebar-visible");
  }

  show() {
    this.setState({ hide: false });
    document.body.classList.remove("sidebar-hidden");
    document.body.classList.add("sidebar-visible");
  }

  componentDidMount() {
    if (window.mw && window.mw.config.get("structuredSearchProps")) {
      const structuredSearchProps = window.mw.config.get("structuredSearchProps");
      console.log("Structured Search Props:", structuredSearchProps);

      // Helper function to apply filters
      const applyFilter = (fieldName, filterValue) => {
        const value = { value: filterValue, label: filterValue };
        if (FormMain && typeof FormMain.addValue === "function") {
          console.log(`Applying filter - Field: ${fieldName}, Value:`, value);
          FormMain.addValue(fieldName, value);
        } else {
          console.warn(`FormMain.addValue is not defined for field: ${fieldName}`);
        }
      };

      // Apply filters dynamically
      if (structuredSearchProps.namespaces) applyFilter("namespaces", structuredSearchProps.namespaces);
      if (structuredSearchProps.category) applyFilter("category", structuredSearchProps.category);
      if (structuredSearchProps.pageType) applyFilter("in_kit", structuredSearchProps.pageType);

      if (structuredSearchProps.title) {
        console.log("title found:", structuredSearchProps.title);
        const titleElement = document.getElementById("parser-search-title");
        if (titleElement) titleElement.textContent = structuredSearchProps.title;
      }

      // Simulating API loading (replace with actual API call event)
      setTimeout(() => {
        this.setState({ loading: false });
      }, 3000);

    } else {
      console.warn("No structuredSearchProps found in mw.config.");
      this.setState({ loading: false }); // Hide loader even if search props are missing
    }

    this.hide();

    EventEmitter.on("FormDataChanged", () => {
      if (this.state.inputs) {
        historySearch.setHistoryFromSearch(this.state.inputs);
        this.forceUpdate();
      }
    });

    settingsGetter.get().then((data) => {
      if (data) {
        FormMain.setBinds(data.binds);
        FormMain.setInputsParams(data.params);
        this.setState({ inputs: data.params }, () => {
          FormMain.setDefaults(data.params);
          historySearch.setSearchFromHistory(data.params);
        });
      }
    });
  }

  render() {
    const { loading, hide, inputs } = this.state;

    // Show loader until results load
    if (loading) {
      return (
        <div className="loading-overlay">
          <i className="search-loader fa-lg fa-solid fa-spinner fa-spin-pulse fa-spin-reverse"></i>
        </div>
      );
    }

    const structuredSearchProps = window.mw?.config.get("structuredSearchProps");
    if (structuredSearchProps?.filter === "hidden") {
      return null;
    }

    let allInputs = [];
    if (inputs) {
      let inputsSorted = Object.values(inputs).sort(utils.sortByWeight);
      for (let inputData of inputsSorted) {
        if (!["topbar", "hide"].includes(inputData.widget.position)) {
          allInputs.push(<FormInput key={inputData.field} inputData={inputData} />);
        }
      }
    }

    return allInputs.length ? (
      <div className={`side-bar${hide ? " hide" : " show"}`}>
        <span className="close-button-wrp">
          <button type="button" className="hide-on-desktop" onClick={this.hide.bind(this)}>
            <i className="fal fa-times"></i>
          </button>
        </span>
        {allInputs}
      </div>
    ) : (
      <div className="side-bar side-bar-loader"></div>
    );
  }
}

export default App;
